<script lang="ts">
 import { page } from '$app/state'; import { collection, getDocs, query, where } from 'firebase/firestore'; import { db } from '$lib/firebase'; import { gradeAssignmentSubmission, getAssignments, getSubmissions } from '$lib/services/assignments'; import { mongoProvider } from '$lib/services/mongo-provider'; import { authState } from '$lib/auth.svelte'; import { canManageCourses } from '$lib/utils/admin'; import { navigate } from '$lib/utils/navigation'; import type { AssignmentSubmission } from '$lib/types/assignment'
 const courseId = $derived(page.params.courseId as string); let submissions = $state<AssignmentSubmission[]>([]); let error = $state(''); $effect(() => { if (!authState.loading) { if (!authState.user || !canManageCourses(authState.user)) navigate('/dashboard'); else load() } }); async function load() { if (mongoProvider.enabled()) { const assignments = await getAssignments(courseId); submissions = (await Promise.all(assignments.map(a => getSubmissions(a.id)))).flat(); return } const snap = await getDocs(query(collection(db, 'assignmentSubmissions'), where('courseId', '==', courseId))); submissions = snap.docs.map(d => ({ id: d.id, ...d.data() } as AssignmentSubmission)) } async function grade(s: AssignmentSubmission, e: Event) { const form = e.currentTarget as HTMLFormElement; const data = new FormData(form); try { await gradeAssignmentSubmission({ submissionId: s.id, pointsEarned: Number(data.get('points')), feedback: String(data.get('feedback') ?? ''), released: data.get('released') === 'on' }); await load() } catch (err) { error = err instanceof Error ? err.message : 'Unable to grade' } }
</script>
<main class="container mx-auto max-w-4xl p-6"><h1 class="text-2xl font-semibold">Assignment gradebook</h1>{#if error}<p class="text-destructive">{error}</p>{/if}{#each submissions as submission}<form class="my-4 rounded border p-4" onsubmit={(e) => { e.preventDefault(); grade(submission, e) }}><p class="whitespace-pre-wrap">{submission.text}</p><div class="mt-2 flex gap-2"><input name="points" type="number" min="0" value={submission.pointsEarned ?? 0} /><input name="feedback" placeholder="Feedback" value={submission.feedback ?? ''} /><label><input name="released" type="checkbox" checked={submission.gradeReleased} /> Release</label><button class="rounded bg-primary px-3 py-1 text-primary-foreground">Save</button></div></form>{/each}</main>
